use crate::aap::caps::kb_read;

struct Node;

/// Upper bound on the question length, in characters, from the node contract.
const MAX_QUESTION_CHARS: usize = 512;

/// Placeholder used when the knowledge base returns nothing, so that
/// `ensures present(knowledge)` holds on every output.
const NO_KNOWLEDGE: &str = "No matching knowledge-base entries were found.";

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;

        // The contract's `requires` already bounds the question; this is a
        // defensive re-bound so the `ensures` holds regardless.
        let question: String = if inner.question.chars().count() > MAX_QUESTION_CHARS {
            inner.question.chars().take(MAX_QUESTION_CHARS).collect()
        } else {
            inner.question
        };

        // The node's only authority: a read-only lookup in the knowledge base.
        let mut knowledge: Vec<String> = kb_read::lookup(&question)
            .into_iter()
            .filter(|entry| !entry.trim().is_empty())
            .collect();

        if knowledge.is_empty() {
            knowledge.push(String::from(NO_KNOWLEDGE));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

I left out both operations requests (the log file append and the metadata-service fetch). The node's `with` clause grants only `aap:caps/kb-read@0.1.0`, so it has no filesystem and no HTTP authority, and importing `http-client` would exceed that grant. If operations wants them, the graph needs to grant this node those capabilities, or do the logging and enrichment in a host-tier node.

